1	import Link from "next/link";
2	
3	// The credit bar, and the warning that fires before the user hits zero.
4	//
5	// Design position: the number alone ("412 credits") is meaningless to someone
6	// who has never seen a build's cost. What people actually want to know is
7	// "how much more can I do?", so the primary line is BUILDS remaining, derived
8	// from that user's own measured average, with the raw credit count secondary.
9	//
10	// The warning appears at 20% of the reference tank, or whenever fewer than two
11	// builds remain — before the dead end, never at it. See lib/credits.ts.
12	
13	export type CreditMeterProps = {
14	  balance: number;
15	  /** That user's measured average credits per build. */
16	  avgBuildCredits: number;
17	  /** Reference "full tank" for the bar — the signup grant. */
18	  reference: number;
19	  canTopUp?: boolean;
20	};
21	
22	export default function CreditMeter({
23	  balance,
24	  avgBuildCredits,
25	  reference,
26	  canTopUp = false,
27	}: CreditMeterProps) {
28	  const buildsLeft = Math.floor(balance / avgBuildCredits);
29	  const pct = Math.max(0, Math.min(100, Math.round((balance / reference) * 100)));
30	
31	  const empty = balance <= 0;
32	  const low = !empty && (pct <= 20 || buildsLeft < 2);
33	
34	  const tone = empty
35	    ? { bar: "bg-red-500", text: "text-red-600 dark:text-red-400" }
36	    : low
37	      ? { bar: "bg-amber-500", text: "text-amber-600 dark:text-amber-500" }
38	      : { bar: "bg-emerald-500", text: "text-black/60 dark:text-white/60" };
39	
40	  return (
41	    <div className="w-44">
42	      <div className="flex items-baseline justify-between gap-2">
43	        <span className="text-sm font-medium tabular-nums">{balance}</span>
44	        <span className="text-xs text-black/50 dark:text-white/50">credits</span>
45	      </div>
46	
47	      <div
48	        className="mt-1.5 h-1.5 w-full overflow-hidden rounded-full bg-black/10 dark:bg-white/10"
49	        role="progressbar"
50	        aria-valuenow={balance}
51	        aria-valuemin={0}
52	        aria-valuemax={reference}
53	        aria-label="Credits remaining"
54	      >
55	        <div className={`h-full rounded-full transition-all ${tone.bar}`} style={{ width: `${pct}%` }} />
56	      </div>
57	
58	      <p className={`mt-1.5 text-xs ${tone.text}`}>
59	        {empty
60	          ? "Out of credits"
61	          : buildsLeft < 1
62	            ? "Not enough for a full build"
63	            : `About ${buildsLeft} more ${buildsLeft === 1 ? "build" : "builds"}`}
64	        {(low || empty) && canTopUp && (
65	          <>
66	            {" · "}
67	            <Link href="/pricing" className="underline underline-offset-2 hover:no-underline">
68	              Top up
69	            </Link>
70	          </>
71	        )}
72	      </p>
73	    </div>
74	  );
75	}
