3	import { useState } from "react";
4	import { api, ApiError } from "@/lib/api";
5	
6	const PACKS = [
7	  { id: "starter", label: "500 credits — $9" },
8	  { id: "builder", label: "2,500 credits — $40" },
9	  { id: "pro", label: "6,000 credits — $90" },
