12	export default function TopUpButton() {
13	  const [loading, setLoading] = useState(false);
14	  const [open, setOpen] = useState(false);
15	
16	  async function buy(packId: string) {
17	    setLoading(true);
18	    try {
19	      const { url } = await api<{ url: string }>("/api/billing/checkout", {
20	        method: "POST",
21	        body: JSON.stringify({ packId }),
22	      });
23	      // .assign() rather than assigning to .href: same navigation, but it is
24	      // a method call instead of a mutation of a value owned by the host,
25	      // which is what react-hooks/immutability (correctly) objects to.
26	      window.location.assign(url);
27	    } catch (err) {
28	      alert(err instanceof ApiError ? err.message : "Couldn't start checkout.");
29	    } finally {
30	      setLoading(false);
31	    }
32	  }
33	
34	  if (!open) {
35	    return (
36	      <button
37	        onClick={() => setOpen(true)}
38	        className="text-sm text-black/60 underline hover:text-black dark:text-white/60 dark:hover:text-white"
39	      >
40	        Top up
41	      </button>
42	    );
43	  }
44	
45	  return (
46	    <div className="flex items-center gap-2">
47	      {PACKS.map((p) => (
48	        <button
49	          key={p.id}
50	          onClick={() => buy(p.id)}
51	          disabled={loading}
52	          className="rounded-lg border border-black/15 px-2 py-1 text-xs disabled:opacity-50 dark:border-white/15"
53	        >
54	          {p.label}
55	        </button>
56	      ))}
57	      <button onClick={() => setOpen(false)} className="text-xs text-black/40 dark:text-white/40">
58	        cancel
59	      </button>
60	    </div>
61	  );
62	}
