1	import { createHmac } from "node:crypto";
2	import { Prisma } from "@prisma/client";
3	import { db } from "@/lib/db";
4	
5	// ── Social rewards: the neutral core ──────────────────────────────────────
6	//
7	// Free credits are REAL model spend on the company card (see lib/credits.ts —
8	// one credit is a fixed $0.002 of underlying spend, so the full 200-credit
9	// sweep is ~$0.40 given away per account). That single fact sets the bar for
10	// everything in this directory: a claim has to be *earned*, and a grant has to
11	// be impossible to repeat.
12	//
13	// This module holds only what both claim paths share — config, identity
14	// hashing, the abuse gates, and the one function that actually writes a grant.
15	// The two paths themselves are deliberately kept apart:
16	//
17	//   ./discord/**  — VERIFIED. Discord's OAuth2 tells us, first-party, whether
18	//                   the authorizing user is in our guild. A real check.
19	//   ./social/**   — UNVERIFIED. Instagram / Facebook / LinkedIn expose no way
20	//                   to ask "does this user follow us". That path is a weaker,
21	//                   self-declared flow and says so, loudly, in its own file.
22	//
23	// Do not blur those two together. The difference is the whole point.
24	
25	/** Credits per platform. 4 platforms x 50 = 200 total, once per account ever. */
26	export const REWARD_CREDITS = 50;
27	
28	export const PLATFORMS = ["discord", "instagram", "facebook", "linkedin"] as const;
29	export type Platform = (typeof PLATFORMS)[number];
30	
31	export const PLATFORM_LABELS: Record<Platform, string> = {
32	  discord: "Discord",
33	  instagram: "Instagram",
34	  facebook: "Facebook",
35	  linkedin: "LinkedIn",
36	};
37	
38	// ── Ledger reason strings are the idempotency key ─────────────────────────
39	//
40	// We cannot add a table (the schema is owned elsewhere), and CreditLedger is
41	// append-only with a free-text `reason`. So `reason` carries the whole state
42	// machine. Two shapes, and only two:
43	//
44	//   reward:<platform>:<identityHash>           delta = +50   a granted reward
45	//   reward:<platform>:pending:<identityHash>   delta =   0   an unverified claim, on hold
46	//
47	// A delta-0 row is a genuine no-op for money: getBalance() reads the newest
48	// row's balanceAfter, and balanceAfter = balance + 0 preserves it exactly;
49	// spentInWindow() only sums delta < 0. So the ledger stays arithmetically
50	// honest while doubling as the only durable store this feature is allowed.
51	//
52	// identityHash is what makes ONE grant per EXTERNAL account, not per Kodely
53	// account — otherwise one Discord login farms fifty signups for 50 credits
54	// each. Because the hash is in the reason string, "has this external identity
55	// ever been rewarded?" is a single indexed-ish scan across ALL users.
56	
57	const REASON_PREFIX = "reward:";
58	
59	export function grantReason(platform: Platform, identityHash: string): string {
60	  return `${REASON_PREFIX}${platform}:${identityHash}`;
61	}
62	
63	export function pendingReason(platform: Platform, identityHash: string): string {
64	  return `${REASON_PREFIX}${platform}:pending:${identityHash}`;
65	}
66	
67	// ── Config ────────────────────────────────────────────────────────────────
68	// Every value is read from process.env at call time. Nothing here is ever
69	// hardcoded, logged, or returned to the browser.
70	
71	/**
72	 * Keying the identity hash with a server-side secret (rather than a plain
73	 * SHA-256) matters more than it looks. Discord snowflakes and Instagram
74	 * handles are low-entropy and enumerable: an unkeyed digest in a `reason`
75	 * column would let anyone with read access to the ledger confirm "is
76	 * @someuser one of your customers?" by brute force. HMAC with a secret they
77	 * do not have removes that entirely.
78	 *
79	 * There is no fallback. Without the key we cannot enforce one-grant-per-
80	 * identity, and one-grant-per-identity is the only thing standing between
81	 * this feature and a credit farm — so with the key absent we grant nothing.
82	 */
83	export function identitySecret(): string | null {
84	  const secret = process.env.KODELY_REWARDS_ID_SALT;
85	  if (!secret || secret.length < 16) return null;
86	  return secret;
87	}
88	
89	export type DiscordConfig = { clientId: string; clientSecret: string; guildId: string };
90	
91	/** Null unless ALL THREE Discord values are present — a half-configured OAuth client fails at Discord, not here. */
92	export function discordConfig(): DiscordConfig | null {
93	  const clientId = process.env.KODELY_DISCORD_CLIENT_ID;
94	  const clientSecret = process.env.KODELY_DISCORD_CLIENT_SECRET;
95	  const guildId = process.env.KODELY_DISCORD_GUILD_ID;
96	  if (!clientId || !clientSecret || !guildId) return null;
97	  return { clientId, clientSecret, guildId };
98	}
99	
100	/** Where we send the user to actually do the thing. Absent URL = reward hidden. */
101	export function platformUrl(platform: Platform): string | null {
102	  const env: Record<Platform, string | undefined> = {
103	    discord: process.env.KODELY_DISCORD_INVITE_URL,
104	    instagram: process.env.KODELY_INSTAGRAM_URL,
105	    facebook: process.env.KODELY_FACEBOOK_URL,
106	    linkedin: process.env.KODELY_LINKEDIN_URL,
107	  };
108	  return env[platform]?.trim() || null;
109	}
110	
111	/**
112	 * A reward is offered only when it is fully configured. Discord additionally
113	 * needs its OAuth client, because without it there is no verification and we
114	 * would be shipping exactly the honour-system button this feature refuses to
115	 * be. Nothing throws: an unconfigured reward simply does not exist.
116	 */
117	export function isPlatformConfigured(platform: Platform): boolean {
118	  if (identitySecret() === null) return false;
119	  if (platformUrl(platform) === null) return false;
120	  if (platform === "discord") return discordConfig() !== null;
121	  return true;
122	}
123	
124	export function configuredPlatforms(): Platform[] {
125	  return PLATFORMS.filter(isPlatformConfigured);
126	}
127	
128	// ── Identity hashing ──────────────────────────────────────────────────────
129	
130	/**
131	 * Stable, secret-keyed fingerprint of an external account. Namespaced by
132	 * platform so the same string on two platforms is two identities, and
133	 * truncated to 96 bits — far past any collision concern at this scale, and
134	 * short enough to keep `reason` readable in an admin query.
135	 *
136	 * Returns null when unkeyed; callers must treat that as "cannot grant".
137	 */
138	export function identityHash(platform: Platform, externalId: string): string | null {
139	  const secret = identitySecret();
140	  if (secret === null) return null;
141	  return createHmac("sha256", secret)
142	    .update(`${platform}:${externalId}`)
143	    .digest("hex")
144	    .slice(0, 24);
145	}
146	
147	// ── Abuse gates ───────────────────────────────────────────────────────────
148	
149	/**
150	 * A brand-new account cannot claim. The farm pattern this feature invites is
151	 * "sign up, claim 200, abandon, repeat", and every step of it is cheap except
152	 * waiting. A day of latency costs a real user nothing (they keep their 750
153	 * signup credits meanwhile) and costs a script the only thing it cannot batch.
154	 */
155	export const MIN_ACCOUNT_AGE_HOURS = 24;
156	
157	/**
158	 * Velocity is the signal that actually matters here. Per-user velocity is
159	 * already bounded — four rewards, ever — so the meaningful measurement is
160	 * GLOBAL: a legitimate day sees a trickle of reward grants, while a farm
161	 * being run against us shows up as a burst. Above the ceiling we stop
162	 * granting entirely and shout in the logs, rather than quietly bleeding
163	 * credits until someone reads a dashboard.
164	 *
165	 * Deliberately a circuit breaker, not a queue: claims are not lost, the user
166	 * is told to come back, and a human gets to look first.
167	 */
168	export const VELOCITY_WINDOW_MINUTES = 60;
169	export const VELOCITY_LIMIT = 25;
170	
171	export type Denial =
172	  | "not_configured"
173	  | "account_too_new"
174	  | "already_claimed"
175	  | "identity_already_used"
176	  | "velocity_tripped";
177	
178	export function accountTooNew(userCreatedAt: Date): boolean {
179	  return Date.now() - userCreatedAt.getTime() < MIN_ACCOUNT_AGE_HOURS * 3_600_000;
180	}
181	
182	async function velocityTripped(tx: Prisma.TransactionClient | typeof db): Promise<boolean> {
183	  const since = new Date(Date.now() - VELOCITY_WINDOW_MINUTES * 60_000);
184	  const recent = await tx.creditLedger.count({
185	    where: { reason: { startsWith: REASON_PREFIX }, delta: { gt: 0 }, createdAt: { gte: since } },
186	  });
187	  return recent >= VELOCITY_LIMIT;
188	}
189	
190	/** Has THIS user already been granted this platform's reward? */
191	export async function hasClaimed(userId: string, platform: Platform): Promise<boolean> {
192	  const row = await db.creditLedger.findFirst({
193	    where: { userId, reason: { startsWith: `${REASON_PREFIX}${platform}:` }, delta: { gt: 0 } },
194	    select: { id: true },
195	  });
196	  return row !== null;
197	}
198	
199	/** Has this EXTERNAL identity been rewarded on any Kodely account, ever? */
200	export async function identityAlreadyUsed(
201	  platform: Platform,
202	  hash: string,
203	  tx: Prisma.TransactionClient | typeof db = db,
204	): Promise<boolean> {
205	  const row = await tx.creditLedger.findFirst({
206	    where: { reason: grantReason(platform, hash), delta: { gt: 0 } },
207	    select: { id: true },
208	  });
209	  return row !== null;
210	}
211	
212	/** The pending (unverified) claim for this user+platform, if one exists. */
213	export async function pendingClaim(userId: string, platform: Platform) {
214	  return db.creditLedger.findFirst({
215	    where: { userId, reason: { startsWith: `${REASON_PREFIX}${platform}:pending:` } },
216	    orderBy: { createdAt: "desc" },
217	    select: { reason: true, createdAt: true },
218	  });
219	}
220	
221	// ── Granting ──────────────────────────────────────────────────────────────
222	
223	/**
224	 * Serialize claims that could collide, using Postgres advisory locks.
225	 *
226	 * Both uniqueness rules here are read-then-write, and CreditLedger has no
227	 * unique constraint on `reason` for us to lean on (we cannot touch the
228	 * schema). Under a double-submitted form or two browser tabs, two requests
229	 * can both read "not yet granted" and both insert — a real double-spend of
230	 * real money. A transaction alone does not fix it: Postgres defaults to READ
231	 * COMMITTED, so the re-read inside the transaction still will not see the
232	 * uncommitted sibling.
233	 *
234	 * Advisory locks do fix it, need no migration, and are released automatically
235	 * when the transaction ends (including on error). Both are taken in a fixed
236	 * order — user first, then identity — so two interleaved claims can never
237	 * deadlock against each other.
238	 *
239	 * $executeRaw, NOT $queryRaw, and that is not a slip. pg_advisory_xact_lock
240	 * returns `void`; $queryRaw tries to deserialize that column and throws
241	 * "Failed to deserialize column of type 'void'". $executeRaw discards rows
242	 * and returns a count, which is all we want. Verified against this app's own
243	 * Postgres: the lock is taken, is re-entrant within the transaction, and is
244	 * released when the transaction ends.
245	 */
246	const LOCK_NAMESPACE = 0x4b4f_4445 | 0; // "KODE"
247	
248	function lockKey(input: string): number {
249	  const secret = identitySecret() ?? "unkeyed";
250	  return createHmac("sha256", secret).update(input).digest().readInt32BE(0);
251	}
252	
253	/**
254	 * Write a grant, or explain why not. The ONLY place in this feature that
255	 * increases a balance.
256	 *
257	 * Mirrors lib/credits.ts `grantCredits` deliberately rather than calling it:
258	 * that helper binds to the global client, and the whole point of this
259	 * function is that the balance read and the ledger insert happen inside the
260	 * same locked transaction. Same row shape, same balanceAfter arithmetic.
261	 */
262	export async function grantReward(
263	  userId: string,
264	  platform: Platform,
265	  hash: string,
266	): Promise<{ ok: true; credits: number } | { ok: false; reason: Denial }> {
267	  if (identitySecret() === null) return { ok: false, reason: "not_configured" };
268	
269	  const userLock = lockKey(`user:${userId}`);
270	  const identityLock = lockKey(`identity:${platform}:${hash}`);
271	
272	  return db.$transaction(async (tx) => {
273	    await tx.$executeRaw`SELECT pg_advisory_xact_lock(${LOCK_NAMESPACE}::int4, ${userLock}::int4)`;
274	    await tx.$executeRaw`SELECT pg_advisory_xact_lock(${LOCK_NAMESPACE}::int4, ${identityLock}::int4)`;
275	
276	    const mine = await tx.creditLedger.findFirst({
277	      where: { userId, reason: { startsWith: `${REASON_PREFIX}${platform}:` }, delta: { gt: 0 } },
278	      select: { id: true },
279	    });
280	    if (mine) return { ok: false as const, reason: "already_claimed" as const };
281	
282	    if (await identityAlreadyUsed(platform, hash, tx)) {
283	      return { ok: false as const, reason: "identity_already_used" as const };
284	    }
285	
286	    if (await velocityTripped(tx)) {
287	      console.error(
288	        `[rewards] velocity ceiling hit (>=${VELOCITY_LIMIT} grants in ${VELOCITY_WINDOW_MINUTES}m) — refusing ${platform} grant. Investigate before raising this.`,
289	      );
290	      return { ok: false as const, reason: "velocity_tripped" as const };
291	    }
292	
293	    const latest = await tx.creditLedger.findFirst({
294	      where: { userId },
295	      orderBy: { createdAt: "desc" },
296	      select: { balanceAfter: true },
297	    });
298	    const balance = latest?.balanceAfter ?? 0;
299	
300	    await tx.creditLedger.create({
301	      data: {
302	        userId,
303	        delta: REWARD_CREDITS,
304	        reason: grantReason(platform, hash),
305	        balanceAfter: balance + REWARD_CREDITS,
306	      },
307	    });
308	
309	    return { ok: true as const, credits: REWARD_CREDITS };
310	  });
311	}
312	
313	/**
314	 * Record an unverified claim as a delta-0 ledger row. Grants nothing.
315	 *
316	 * The zero delta is load-bearing and slightly delicate: getBalance() reads the
317	 * NEWEST row's balanceAfter, so this row has to carry the balance forward
318	 * exactly or it would silently rewrite someone's balance. Hence the same
319	 * locked read-then-insert as grantReward rather than a bare create with a
320	 * balance read from outside the transaction.
321	 *
322	 * (A build charge committing between this transaction's read and its insert
323	 * would still be clobbered — that race is inherent to the ledger's
324	 * read-then-write shape and predates this feature; see chargeForBuild and
325	 * grantCredits in lib/credits.ts, which have it too. The lock at least stops
326	 * rewards racing rewards, which is the part this feature introduced.)
327	 */
328	export async function recordPending(
329	  userId: string,
330	  platform: Platform,
331	  hash: string,
332	): Promise<{ ok: true } | { ok: false; reason: Denial }> {
333	  const userLock = lockKey(`user:${userId}`);
334	  const identityLock = lockKey(`identity:${platform}:${hash}`);
335	
336	  return db.$transaction(async (tx) => {
337	    await tx.$executeRaw`SELECT pg_advisory_xact_lock(${LOCK_NAMESPACE}::int4, ${userLock}::int4)`;
338	    await tx.$executeRaw`SELECT pg_advisory_xact_lock(${LOCK_NAMESPACE}::int4, ${identityLock}::int4)`;
339	
340	    // Anything at all for this user+platform — granted or already pending —
341	    // means we are done. Re-declaring would otherwise restart the hold clock
342	    // and let someone shop for a handle that passes.
343	    const existing = await tx.creditLedger.findFirst({
344	      where: { userId, reason: { startsWith: `${REASON_PREFIX}${platform}:` } },
345	      select: { id: true },
346	    });
347	    if (existing) return { ok: false as const, reason: "already_claimed" as const };
348	
349	    // Re-checked INSIDE the lock, not just at the route. Two accounts
350	    // declaring the same handle at the same moment would both pass an
351	    // unlocked check, and the loser would only find out 72 hours later when
352	    // their claim was refused.
353	    const taken = await tx.creditLedger.findFirst({
354	      where: {
355	        reason: { in: [grantReason(platform, hash), pendingReason(platform, hash)] },
356	      },
357	      select: { id: true },
358	    });
359	    if (taken) return { ok: false as const, reason: "identity_already_used" as const };
360	
361	    const latest = await tx.creditLedger.findFirst({
362	      where: { userId },
363	      orderBy: { createdAt: "desc" },
364	      select: { balanceAfter: true },
365	    });
366	
367	    await tx.creditLedger.create({
368	      data: {
369	        userId,
370	        delta: 0,
371	        reason: pendingReason(platform, hash),
372	        balanceAfter: latest?.balanceAfter ?? 0,
373	      },
374	    });
375	
376	    return { ok: true as const };
377	  });
378	}
379	
380	/** Pull the identity hash back out of a `reward:<platform>:pending:<hash>` reason. */
381	export function hashFromPendingReason(reason: string): string | null {
382	  const parts = reason.split(":");
383	  return parts.length === 4 && parts[0] === "reward" && parts[2] === "pending"
384	    ? parts[3]
385	    : null;
386	}
387	
388	// ── Status, as the settings page sees it ──────────────────────────────────
389	
390	export type RewardState =
391	  | "available" // nothing done yet
392	  | "pending" // unverified claim recorded, hold period still running
393	  | "claimable" // unverified claim, hold elapsed, credits waiting
394	  | "claimed" // granted
395	  | "locked"; // account too new
396	
397	export type RewardStatus = {
398	  platform: Platform;
399	  label: string;
400	  url: string;
401	  credits: number;
402	  verified: boolean;
403	  state: RewardState;
404	  /** ISO timestamp a pending claim becomes claimable. */
405	  readyAt: string | null;
406	  /**
407	   * Whole hours left on the hold, computed server-side on purpose. The client
408	   * renders this number rather than diffing readyAt against its own clock,
409	   * which would differ between the server render and hydration and trip a
410	   * mismatch warning on every page load.
411	   */
412	  readyInHours: number | null;
413	};
414	
415	/** Hours an unverified claim sits before it pays out. See ./social/_unverified.ts. */
416	export const UNVERIFIED_HOLD_HOURS = 72;
417	
418	export async function rewardStatuses(user: {
419	  id: string;
420	  createdAt: Date;
421	}): Promise<RewardStatus[]> {
422	  const platforms = configuredPlatforms();
423	  if (platforms.length === 0) return [];
424	
425	  const tooNew = accountTooNew(user.createdAt);
426	
427	  return Promise.all(
428	    platforms.map(async (platform): Promise<RewardStatus> => {
429	      const url = platformUrl(platform) as string;
430	      const verified = platform === "discord";
431	      const base = {
432	        platform,
433	        label: PLATFORM_LABELS[platform],
434	        url,
435	        credits: REWARD_CREDITS,
436	        verified,
437	      };
438	
439	      if (await hasClaimed(user.id, platform)) {
440	        return { ...base, state: "claimed", readyAt: null, readyInHours: null };
441	      }
442	      if (tooNew) return { ...base, state: "locked", readyAt: null, readyInHours: null };
443	
444	      if (!verified) {
445	        const pending = await pendingClaim(user.id, platform);
446	        if (pending) {
447	          const ready = new Date(
448	            pending.createdAt.getTime() + UNVERIFIED_HOLD_HOURS * 3_600_000,
449	          );
450	          const msLeft = ready.getTime() - Date.now();
451	          return {
452	            ...base,
453	            state: msLeft <= 0 ? "claimable" : "pending",
454	            readyAt: ready.toISOString(),
455	            readyInHours: msLeft <= 0 ? 0 : Math.ceil(msLeft / 3_600_000),
456	          };
457	        }
458	      }
459	
460	      return { ...base, state: "available", readyAt: null, readyInHours: null };
461	    }),
462	  );
463	}
464	
465	// ── Misc ──────────────────────────────────────────────────────────────────
466	
467	/**
468	 * Behind the Cloudflare -> host-nginx -> VM-nginx chain, req.url is the
469	 * internal 127.0.0.1:PORT the proxy forwards to, and X-Forwarded-Proto gets
470	 * clobbered by the Flexible-SSL hops. Same derivation the Google OAuth routes
471	 * use — the redirect_uri must match byte-for-byte across start and callback.
472	 */
473	export function originFromRequest(req: Request): string {
474	  const host = req.headers.get("host");
475	  if (!host) return new URL(req.url).origin;
476	  return `https://${host}`;
477	}
