237	          // only reachable via the abort path (see the `break` above).
238	        } else {
239	          succeeded = true;
240	
241	          // Replace the compiled tree with the new build output.
242	          await db.$transaction([
243	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
244	            ...(Object.keys(buildOutput).length > 0
245	              ? [
246	                  db.projectFile.createMany({
247	                    data: Object.entries(buildOutput).map(([path, content]) => ({
248	                      projectId: project.id,
249	                      path,
250	                      content,
251	                      published: false,
252	                      kind: "build",
253	                    })),
254	                  }),
255	                ]
256	              : []),
257	          ]);
258	
259	          const micros = costMicros(model, totals);
260	          const credits = creditsFor(micros);
261	          // A zero charge writes no ledger row. The ledger is a financial
262	          // record; an entry that moves nothing is noise in a statement a
263	          // customer may one day be reading to understand their bill.
264	          const remaining =
265	            credits > 0
266	              ? await chargeForBuild(user.id, build.id, credits)
267	              : await getBalance(user.id);
268	
269	          const sourceFiles = await readSourceFiles();
270	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
271	
272	          await db.build.update({
273	            where: { id: build.id },
274	            data: {
275	              status: "SUCCEEDED",
276	              model,
277	              endedAt: new Date(),
278	              inputTokens: totals.inputTokens,
279	              outputTokens: totals.outputTokens,
280	              cacheReadTokens: totals.cacheReadTokens,
281	              cacheWriteTokens: totals.cacheWriteTokens,
282	              filesWritten,
283	              repairAttempts,
284	              costMicros: micros,
285	              creditsCharged: credits,
286	              filesSnapshot,
287	            },
288	          });
289	
290	          track(EVENTS.buildSucceeded, {
291	            userId: user.id,
292	            props: {
293	              buildId: build.id,
294	              projectId: project.id,
295	              kind,
296	              model,
297	              repairAttempts,
298	              filesWritten,
299	              credits,
300	              remaining,
301	            },
302	          });
303	
304	          if (lastReply.trim()) {
305	            await db.message.create({
306	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
307	            });
308	          }
309	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
310	
311	          // buildId travels to the client so it can attach a rating to this
312	          // specific build (see app/api/feedback/route.ts).
313	          send({ type: "done", credits, remaining, filesWritten, buildId: build.id });
314	        }
315	
316	        if (!succeeded) {
317	          await db.build.update({
318	            where: { id: build.id },
319	            data: {
320	              status: "FAILED",
321	              endedAt: new Date(),
322	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
323	              filesWritten,
324	              repairAttempts,
325	              creditsCharged: 0,
326	              // Record the model on failure too, when we got far enough to
327	              // learn it. It used to be written only on success, so every
328	              // failed build had a blank Model column — which made it
329	              // impossible to attribute a spike in failures to a model change,
330	              // exactly when you most need to.
331	              ...(model ? { model } : {}),
332	            },
333	          });
334	
335	          track(EVENTS.buildFailed, {
336	            userId: user.id,
337	            props: {
338	              buildId: build.id,
339	              projectId: project.id,
340	              kind,
341	              repairAttempts,
342	              reason: abortController.signal.aborted ? "aborted" : "no_output",
343	            },
344	          });
345	        }
346	      } catch (error) {
347	        // A build that fails is never charged — that is the product promise,
348	        // so the ledger is deliberately untouched on this path.
349	        const message =
350	          error instanceof Error ? error.message : "The build failed unexpectedly.";
351	        console.error("[kodely] build failed", build.id, error);
352	
353	        await db.build.update({
354	          where: { id: build.id },
355	          data: {
356	            status: "FAILED",
357	            endedAt: new Date(),
358	            error: message.slice(0, 1000),
359	            filesWritten,
360	            repairAttempts,
361	            creditsCharged: 0,
362	            // See the note on the other failure path — a blank model makes a
363	            // failure impossible to attribute.
364	            ...(model ? { model } : {}),
365	          },
366	        });
367	
368	        track(EVENTS.buildFailed, {
369	          userId: user.id,
370	          props: {
371	            buildId: build.id,
372	            projectId: project.id,
373	            kind,
374	            repairAttempts,
375	            reason: "error",
376	          },
377	        });
378	
379	        send({ type: "error", message });
380	      } finally {
381	        try {
382	          controller.close();
383	        } catch {
384	          // already closed by the client disconnect path
385	        }
386	      }
387	    },
388	    cancel() {
389	      // The client disconnected — stop the in-flight Anthropic request
390	      // rather than let it run to completion for a response nobody reads.
391	      abortController.abort();
392	    },
393	  });
394	
395	  return new Response(stream, {
396	    headers: {
397	      "Content-Type": "text/event-stream; charset=utf-8",
398	      "Cache-Control": "no-cache, no-transform",
399	      Connection: "keep-alive",
400	    },
401	  });
402	}
