import { PLATFORM_LABELS } from "@/app/api/rewards/_lib";

// Presentation helpers for the customer's own credit statement.
//
// The admin equivalent (app/admin/users/ui.tsx `reasonLabel`) decodes the same
// strings, but it is allowed to fall back to echoing the raw `reason` and to
// expose it on hover. This one is not. `CreditLedger.reason` is free text that
// carries a Stripe Checkout session id and an HMAC of a customer's external
// social account (see app/api/rewards/_lib.ts), and neither of those belongs in
// front of the person they are about. So every branch here returns wording we
// wrote, and the unknown branch returns wording too — it never passes the
// string through.

export type ReasonDescription = {
  /** Plain-English label for the "What" column. */
  label: string;
  /** Optional second line. Never contains an id, session or hash. */
  detail?: string;
};

/**
 * Decode one ledger `reason` into something a customer can read.
 *
 * The four shapes that exist today, all written by our own code:
 *   "build"                                     a charge for a successful build
 *   "signup_grant"                              the free credits at signup
 *   "stripe:<checkout session id>"              a paid top-up (webhook only)
 *   "reward:<platform>:<hash>"                  a granted social reward
 *   "reward:<platform>:pending:<hash>"          a claim on hold, delta 0
 */
export function describeReason(reason: string, delta: number): ReasonDescription {
  if (reason === "build") {
    return { label: "Site build" };
  }

  if (reason === "signup_grant") {
    return { label: "Welcome credits", detail: "Added free when you created your account" };
  }

  if (reason.startsWith("stripe:")) {
    // Everything after the prefix is the Stripe Checkout session id. It
    // identifies a payment session, is meaningless to the customer, and stops
    // here. The pack size is already visible in the Change column.
    return { label: "Credit purchase", detail: "Paid top-up" };
  }

  if (reason.startsWith("reward:")) {
    const parts = reason.split(":");
    // Platform name only — the trailing segment is a keyed hash of the external
    // account and is never rendered.
    const name = (PLATFORM_LABELS as Record<string, string | undefined>)[parts[1] ?? ""] ?? "Social";

    if (parts[2] === "pending") {
      // A zero-delta row: the claim is recorded but nothing has moved yet.
      return {
        label: `${name} reward — on hold`,
        detail: "Recorded. The credits are added once the hold period is up.",
      };
    }
    return { label: `${name} reward` };
  }

  // Unrecognised shape. `reason` is free text on an append-only table, so it
  // could be anything — including something with an id in it. Describe it from
  // the direction of the money instead of echoing it.
  if (delta > 0) return { label: "Credits added" };
  if (delta < 0) return { label: "Credits used" };
  return { label: "Account note" };
}

// Fixed to UTC so the string is the same on every render and does not depend on
// the server's timezone. Rendered server-side only, so there is no client clock
// to disagree with it.
const DAY = new Intl.DateTimeFormat("en-GB", {
  day: "2-digit",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

const TIME = new Intl.DateTimeFormat("en-GB", {
  hour: "2-digit",
  minute: "2-digit",
  hour12: false,
  timeZone: "UTC",
});

export function formatDay(d: Date): string {
  return DAY.format(d);
}

export function formatTime(d: Date): string {
  return TIME.format(d);
}

/** "+750" / "-472" / "0" — the sign is the whole point of a statement column. */
export function signedCredits(delta: number): string {
  return delta > 0 ? `+${delta.toLocaleString("en-GB")}` : delta.toLocaleString("en-GB");
}

export function formatCredits(n: number): string {
  return n.toLocaleString("en-GB");
}

import type { ReactNode } from "react";
import Link from "next/link";
import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import {
  averageBuildCredits,
  estimateCredits,
  getBalance,
  getSpendCapStatus,
  spentInWindow,
} from "@/lib/credits";
import { CREDIT_PACKS, billingEnabled } from "@/lib/stripe";
import TopUpButton from "../TopUpButton";
import {
  describeReason,
  formatCredits,
  formatDay,
  formatTime,
  signedCredits,
} from "./ledger";

export const dynamic = "force-dynamic";

// The customer's own view of the ledger. Read-only, end to end: this page never
// writes to CreditLedger, never grants or deducts, and the only money action it
// offers is the checkout TopUpButton already owned.
//
// The ledger is append-only and auditable by design (see prisma/schema.prisma
// and lib/credits.ts) — it was just never shown to the person it is about. This
// page is that, and nothing more.

const PAGE_SIZE = 25;

export default async function BillingPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const cap = await getSpendCapStatus(user.id);

  const [balance, spent, avgBuildCredits, measuredBuilds, totalEntries] = await Promise.all([
    getBalance(user.id),
    // getSpendCapStatus skips the spend query when uncapped; this page needs it
    // either way. Same shape as app/settings/page.tsx so both report the same
    // number the cap actually enforces.
    cap.cap === null ? spentInWindow(user.id) : Promise.resolve(cap.spent),
    averageBuildCredits(user.id),
    // averageBuildCredits falls back to a global constant when a user has no
    // history. That constant is a reasonable default for "builds remaining" but
    // it is NOT a measurement of this person, so the tile below only shows an
    // average when this count says there is one.
    db.build.count({
      where: { project: { userId: user.id }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
    }),
    db.creditLedger.count({ where: { userId: user.id } }),
  ]);

  const pageCount = Math.max(1, Math.ceil(totalEntries / PAGE_SIZE));
  const requested = Number((await searchParams).page);
  const page =
    Number.isInteger(requested) && requested >= 1 ? Math.min(requested, pageCount) : 1;

  const entries = await db.creditLedger.findMany({
    where: { userId: user.id },
    // Same ordering as getBalance in lib/credits.ts, with `id` as a stable
    // tiebreak — so the top row on page 1 IS the row that defines the balance.
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    skip: (page - 1) * PAGE_SIZE,
    take: PAGE_SIZE,
    select: {
      id: true,
      createdAt: true,
      delta: true,
      reason: true,
      balanceAfter: true,
      build: { select: { project: { select: { id: true, name: true } } } },
    },
  });

  const canTopUp = billingEnabled();
  const create = estimateCredits("create");
  const edit = estimateCredits("edit");

  const firstIndex = totalEntries === 0 ? 0 : (page - 1) * PAGE_SIZE + 1;
  const lastIndex = (page - 1) * PAGE_SIZE + entries.length;

  return (
    <main id="main-content" tabIndex={-1} className="mx-auto max-w-4xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/dashboard"
          className={`rounded text-sm text-black/60 underline underline-offset-2 hover:no-underline dark:text-white/60 ${FOCUS}`}
        >
          ← Back
        </Link>
        <h1 className="mt-3 text-lg font-semibold tracking-tight">Billing &amp; credits</h1>
        <p className="text-sm text-black/60 dark:text-white/60">{user.email}</p>
      </div>

      {/* ── Where you stand ────────────────────────────────────────────── */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <Tile
          label="Credits left"
          value={formatCredits(balance)}
          hint={balance === 0 ? "You're out of credits" : "Credits don't expire"}
        />
        <Tile
          label="Used in the last 30 days"
          value={formatCredits(spent)}
          hint="Rolling window, not a calendar month"
        />
        <Tile
          label="Your average build"
          value={measuredBuilds > 0 ? formatCredits(avgBuildCredits) : "—"}
          hint={
            measuredBuilds > 0
              ? `Measured across your recent builds (${measuredBuilds} charged so far)`
              : "Nothing measured yet — you haven't been charged for a build"
          }
        />
      </div>

      {/* ── Spending cap ───────────────────────────────────────────────── */}
      <section className="mt-4 rounded-xl border border-black/10 p-5 dark:border-white/10">
        <h2 className="text-sm font-medium">Spending cap</h2>
        {cap.cap === null ? (
          <p className="mt-1 text-sm text-black/60 dark:text-white/60">
            You haven&apos;t set one. A cap stops builds once you&apos;ve spent a number of credits
            you choose in any 30-day period.{" "}
            <Link
              href="/settings"
              className={`rounded underline underline-offset-2 hover:no-underline ${FOCUS}`}
            >
              Set a cap in Settings
            </Link>
            .
          </p>
        ) : (
          <>
            <p className="mt-1 text-sm text-black/60 dark:text-white/60">
              <span className="font-medium tabular-nums text-black dark:text-white">
                {formatCredits(cap.spent)}
              </span>{" "}
              of{" "}
              <span className="font-medium tabular-nums text-black dark:text-white">
                {formatCredits(cap.cap)}
              </span>{" "}
              credits used in the last 30 days
              {cap.reached
                ? " — builds are paused until this drops below your cap, or you change it."
                : ` · ${formatCredits(cap.remaining)} left under your cap.`}
            </p>
            <div
              className="mt-3 h-1.5 w-full overflow-hidden rounded-full bg-black/10 dark:bg-white/10"
              role="progressbar"
              aria-valuenow={Math.min(cap.spent, cap.cap)}
              aria-valuemin={0}
              aria-valuemax={cap.cap}
              aria-label="Credits used against your spending cap"
            >
              <div
                className={`h-full rounded-full ${
                  cap.reached ? "bg-amber-500" : "bg-black/70 dark:bg-white/70"
                }`}
                style={{ width: `${Math.min(100, Math.round((cap.spent / cap.cap) * 100))}%` }}
              />
            </div>
            <p className="mt-3 text-xs text-black/50 dark:text-white/50">
              It&apos;s your cap — we never raise it for you.{" "}
              <Link
                href="/settings"
                className={`rounded underline underline-offset-2 hover:no-underline ${FOCUS}`}
              >
                Change it in Settings
              </Link>
              .
            </p>
          </>
        )}
      </section>

      {/* ── Adding credits ─────────────────────────────────────────────── */}
      <section className="mt-4 rounded-xl border border-black/10 p-5 dark:border-white/10">
        <h2 className="text-sm font-medium">Add credits</h2>
        {canTopUp ? (
          <>
            <p className="mt-1 mb-3 text-sm text-black/60 dark:text-white/60">
              One-off packs. Nothing recurring, and no card is stored by Kodely.
            </p>
            {/* Packs come from the server's own CREDIT_PACKS table so this page
                can't drift from what checkout will actually charge. */}
            <TopUpButton packs={CREDIT_PACKS.map((p) => ({ id: p.id, label: p.label }))} />
          </>
        ) : (
          // Stripe is not configured on this deployment. Everything else on this
          // page still works — the statement below is complete and unaffected.
          <TopUpButton enabled={false} />
        )}
      </section>

      {/* ── The statement ──────────────────────────────────────────────── */}
      <section className="mt-4 rounded-xl border border-black/10 p-5 dark:border-white/10">
        <h2 className="text-sm font-medium">Credit statement</h2>
        <p className="mt-0.5 text-xs text-black/50 dark:text-white/50">
          Newest first. Every row is one entry in an append-only record — nothing here is ever
          edited or removed — and the balance column is your balance immediately after that entry.
        </p>

        <div className="mt-4">
          {entries.length === 0 ? (
            <div className="rounded-xl border border-dashed border-black/15 p-10 text-center text-sm text-black/60 dark:border-white/15 dark:text-white/60">
              No credit activity yet.
            </div>
          ) : (
            <div className="overflow-x-auto rounded-xl border border-black/10 dark:border-white/10">
              <table className="w-full text-left text-sm">
                <caption className="sr-only">
                  Your credit entries, newest first, page {page} of {pageCount}
                </caption>
                <thead>
                  <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                    <th scope="col" className="px-3 py-2 font-medium sm:px-4">
                      When (UTC)
                    </th>
                    <th scope="col" className="px-3 py-2 font-medium sm:px-4">
                      What for
                    </th>
                    <th scope="col" className="px-3 py-2 text-right font-medium sm:px-4">
                      Change
                    </th>
                    <th scope="col" className="px-3 py-2 text-right font-medium sm:px-4">
                      Balance
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-black/10 dark:divide-white/10">
                  {entries.map((e) => {
                    const what = describeReason(e.reason, e.delta);
                    const project = e.build?.project ?? null;
                    return (
                      <tr key={e.id}>
                        <td className="whitespace-nowrap px-3 py-3 align-top tabular-nums text-black/70 dark:text-white/70 sm:px-4">
                          {formatDay(e.createdAt)}
                          <span className="block text-xs text-black/40 dark:text-white/40">
                            {formatTime(e.createdAt)}
                          </span>
                        </td>
                        <td className="px-3 py-3 align-top sm:px-4">
                          <span className="block break-words">{what.label}</span>
                          {project ? (
                            <Link
                              href={`/projects/${project.id}`}
                              className={`mt-0.5 block break-words rounded text-xs text-black/50 underline underline-offset-2 hover:no-underline dark:text-white/50 ${FOCUS}`}
                            >
                              {project.name}
                            </Link>
                          ) : what.detail ? (
                            <span className="mt-0.5 block break-words text-xs text-black/50 dark:text-white/50">
                              {what.detail}
                            </span>
                          ) : null}
                        </td>
                        <td
                          className={`whitespace-nowrap px-3 py-3 text-right align-top font-medium tabular-nums sm:px-4 ${
                            e.delta > 0
                              ? "text-emerald-600 dark:text-emerald-400"
                              : e.delta < 0
                                ? "text-red-600 dark:text-red-400"
                                : "text-black/40 dark:text-white/40"
                          }`}
                        >
                          {signedCredits(e.delta)}
                        </td>
                        <td className="whitespace-nowrap px-3 py-3 text-right align-top tabular-nums text-black/70 dark:text-white/70 sm:px-4">
                          {formatCredits(e.balanceAfter)}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {totalEntries > 0 && (
          <nav
            aria-label="Credit statement pages"
            className="mt-4 flex flex-wrap items-center justify-between gap-3"
          >
            <p className="text-xs text-black/50 dark:text-white/50">
              Showing <span className="tabular-nums">{firstIndex}</span>–
              <span className="tabular-nums">{lastIndex}</span> of{" "}
              <span className="tabular-nums">{totalEntries}</span>
            </p>
            <div className="flex items-center gap-2">
              <PageLink page={page - 1} disabled={page <= 1} rel="prev">
                ← Newer
              </PageLink>
              <PageLink page={page + 1} disabled={page >= pageCount} rel="next">
                Older →
              </PageLink>
            </div>
          </nav>
        )}

        <p className="mt-4 text-xs text-black/50 dark:text-white/50">
          A build only reaches this statement if it succeeded and had measured model cost. A build
          that fails is recorded with its true cost and charged nothing, so it never appears here.
        </p>
      </section>

      {/* ── What a build costs ─────────────────────────────────────────── */}
      <section className="mt-4 rounded-xl border border-black/10 p-5 dark:border-white/10">
        <h2 className="text-sm font-medium">What a build costs</h2>
        <p className="mt-1 text-sm text-black/60 dark:text-white/60">
          Credits come off the model usage we actually metered, after a build succeeds — never a
          flat guess up front. If a build doesn&apos;t compile and Kodely repairs it before
          succeeding, the whole run is charged once, together: the first attempt and the repair.
        </p>

        <dl className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">
          <RangeRow term="Building a new site" low={create.low} high={create.high} />
          <RangeRow term="Making an edit" low={edit.low} high={edit.high} />
        </dl>

        <p className="mt-4 text-xs text-black/50 dark:text-white/50">
          Treat those as wide brackets, not predictions. They are drawn from only two builds we have
          measured end to end — 144 credits and 472 credits — which is a more-than-threefold spread
          and nowhere near enough to call a typical build. That is why there is no single figure
          here. Your own builds can land outside these brackets, and the numbers in your statement
          above are the only ones that are actually about you.
        </p>
      </section>
    </main>
  );
}

