function RangeRow({ term, low, high }: { term: string; low: number; high: number }) {
  return (
    <div className="rounded-xl border border-black/10 p-4 dark:border-white/10">
      <dt className="text-xs text-black/50 dark:text-white/50">{term}</dt>
      <dd className="mt-1 text-sm tabular-nums">
        somewhere between {formatCredits(low)} and {formatCredits(high)} credits
      </dd>
    </div>
  );
}

function PageLink({
  page,
  disabled,
  rel,
  children,
}: {
  page: number;
  disabled: boolean;
  rel: "prev" | "next";
  children: ReactNode;
}) {
  const label = rel === "prev" ? "Newer entries" : "Older entries";

  if (disabled) {
    return (
      <span className="rounded-lg border border-black/10 px-2.5 py-1 text-xs text-black/30 dark:border-white/10 dark:text-white/30">
        {children}
      </span>
    );
  }

  return (
    <Link
      href={page <= 1 ? "/dashboard/billing" : `/dashboard/billing?page=${page}`}
      rel={rel}
      aria-label={label}
      className={`rounded-lg border border-black/15 px-2.5 py-1 text-xs text-black/70 hover:border-black/40 hover:text-black dark:border-white/15 dark:text-white/70 dark:hover:border-white/40 dark:hover:text-white ${FOCUS}`}
    >
      {children}
    </Link>
  );
}

