"use client";

import { useState } from "react";
import { api, ApiError } from "@/lib/api";

export type TopUpPack = { id: string; label: string };

// Mirrors CREDIT_PACKS in lib/stripe.ts. It stays here as a DEFAULT because the
// dashboard header renders <TopUpButton /> with no props; anywhere that can
// reach the server (the billing page does) should pass the real table instead so
// the labels can't drift from what checkout will charge.
const DEFAULT_PACKS: TopUpPack[] = [
  { id: "starter", label: "500 credits — $9" },
  { id: "builder", label: "2,500 credits — $40" },
  { id: "pro", label: "6,000 credits — $90" },
];

export type TopUpButtonProps = {
  /**
   * False when Stripe isn't configured on this deployment. The dashboard gates
   * this component behind billingEnabled() and so never passes it, but the
   * billing page renders regardless — a statement is still worth reading with
   * payments switched off. In that case say so plainly rather than showing a
   * button whose checkout call would come back 503.
   */
  enabled?: boolean;
  packs?: TopUpPack[];
};

export default function TopUpButton({ enabled = true, packs = DEFAULT_PACKS }: TopUpButtonProps) {
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);

  async function buy(packId: string) {
    setLoading(true);
    try {
      const { url } = await api<{ url: string }>("/api/billing/checkout", {
        method: "POST",
        body: JSON.stringify({ packId }),
      });
      // .assign() rather than assigning to .href: same navigation, but it is
      // a method call instead of a mutation of a value owned by the host,
      // which is what react-hooks/immutability (correctly) objects to.
      window.location.assign(url);
    } catch (err) {
      alert(err instanceof ApiError ? err.message : "Couldn't start checkout.");
    } finally {
      setLoading(false);
    }
  }

  if (!enabled) {
    return (
      <p className="text-sm text-black/60 dark:text-white/60">
        Top-ups aren&apos;t available right now — card payments aren&apos;t set up on this
        deployment. Your credits and everything on this page are unaffected.
      </p>
    );
  }

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        aria-expanded={false}
        className={`rounded text-sm text-black/60 underline hover:text-black dark:text-white/60 dark:hover:text-white ${FOCUS}`}
      >
        Top up
      </button>
    );
  }

  return (
    <div className="flex flex-wrap items-center gap-2">
      {packs.map((p) => (
        <button
          key={p.id}
          onClick={() => buy(p.id)}
          disabled={loading}
          className={`rounded-lg border border-black/15 px-2 py-1 text-xs tabular-nums disabled:opacity-50 dark:border-white/15 ${FOCUS}`}
        >
          {p.label}
        </button>
      ))}
      <button
        onClick={() => setOpen(false)}
        className={`rounded text-xs text-black/40 dark:text-white/40 ${FOCUS}`}
      >
        cancel
      </button>
    </div>
  );
}

// Same focus treatment as the rest of the dashboard (app/dashboard/ProjectRow.tsx).
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";

